const reviewWithdrawal = `-- name: ReviewWithdrawal :one
UPDATE chain.withdrawals
SET status = $3, failure_reason = $4, reviewed_by = $5, reviewed_at = now(),
    review_note = $6, version = version + 1, updated_at = now()
WHERE tenant_id = $1 AND id = $2
RETURNING id, tenant_id, account_id, asset, amount, to_address, chain_id, idempotency_key, request_hash, status, failure_reason, reviewed_by, reviewed_at, review_note, hold_entry_id, correlation_id, version, created_at, updated_at, nonce, raw_tx, tx_hash, broadcast_at, replacements, block_number, gas_cost, cancel_tx_hash, resolve_action, resolve_note, resolve_requested_by, resolve_requested_at, resolve_error
`

type ReviewWithdrawalParams struct {
	TenantID      string
	ID            string
	Status        string
	FailureReason *string
	ReviewedBy    *string
	ReviewNote    *string
}

// The admin decision. reviewed_by and reviewed_at are written together
// because 0010 requires them to be both set or both null.
func (q *Queries) ReviewWithdrawal(ctx context.Context, arg ReviewWithdrawalParams) (ChainWithdrawal, error) {
	row := q.db.QueryRow(ctx, reviewWithdrawal,
		arg.TenantID,
		arg.ID,
		arg.Status,
		arg.FailureReason,
		arg.ReviewedBy,
		arg.ReviewNote,
	)
	var i ChainWithdrawal
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.AccountID,
		&i.Asset,
		&i.Amount,
		&i.ToAddress,
		&i.ChainID,
		&i.IdempotencyKey,
		&i.RequestHash,
		&i.Status,
		&i.FailureReason,
		&i.ReviewedBy,
		&i.ReviewedAt,
		&i.ReviewNote,
		&i.HoldEntryID,
		&i.CorrelationID,
		&i.Version,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Nonce,
		&i.RawTx,
		&i.TxHash,
		&i.BroadcastAt,
		&i.Replacements,
		&i.BlockNumber,
		&i.GasCost,
		&i.CancelTxHash,
		&i.ResolveAction,
		&i.ResolveNote,
		&i.ResolveRequestedBy,
		&i.ResolveRequestedAt,
		&i.ResolveError,
	)
	return i, err
}

const sumWithdrawnSince = `-- name: SumWithdrawnSince :one
SELECT COALESCE(SUM(amount), 0)::numeric(36,18) AS total
FROM chain.withdrawals
WHERE tenant_id = $1 AND account_id = $2 AND asset = $3
  AND created_at >= $4
  AND status NOT IN ('rejected', 'failed')
`

type SumWithdrawnSinceParams struct {
	TenantID  string
	AccountID string
	Asset     string
	CreatedAt time.Time
}

// The daily limit of §6.4.2. Everything that is not rejected or failed counts
// against it: a withdrawal still in review is money the account has already
// committed, and letting a second one through while the first waits would be
// a way to spend the limit twice.
func (q *Queries) SumWithdrawnSince(ctx context.Context, arg SumWithdrawnSinceParams) (pgtype.Numeric, error) {
	row := q.db.QueryRow(ctx, sumWithdrawnSince,
		arg.TenantID,
		arg.AccountID,
		arg.Asset,
		arg.CreatedAt,
	)
	var total pgtype.Numeric
	err := row.Scan(&total)
	return total, err
}

